public class InnerKnowledgeBaseRedshiftQueryEngineConfigurationFactory(Action<Humidifier.Bedrock.KnowledgeBaseTypes.RedshiftQueryEngineConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Bedrock.KnowledgeBaseTypes.RedshiftQueryEngineConfiguration>
{

    internal InnerKnowledgeBaseRedshiftProvisionedConfigurationFactory ProvisionedConfigurationFactory { get; set; }

    internal InnerKnowledgeBaseRedshiftServerlessConfigurationFactory ServerlessConfigurationFactory { get; set; }

    protected override Humidifier.Bedrock.KnowledgeBaseTypes.RedshiftQueryEngineConfiguration Create()
    {
        var redshiftQueryEngineConfigurationResult = CreateRedshiftQueryEngineConfiguration();
        factoryAction?.Invoke(redshiftQueryEngineConfigurationResult);

        return redshiftQueryEngineConfigurationResult;
    }

    private Humidifier.Bedrock.KnowledgeBaseTypes.RedshiftQueryEngineConfiguration CreateRedshiftQueryEngineConfiguration()
    {
        var redshiftQueryEngineConfigurationResult = new Humidifier.Bedrock.KnowledgeBaseTypes.RedshiftQueryEngineConfiguration();

        return redshiftQueryEngineConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.KnowledgeBaseTypes.RedshiftQueryEngineConfiguration result)
    {
        base.CreateChildren(result);

        result.ProvisionedConfiguration ??= ProvisionedConfigurationFactory?.Build();
        result.ServerlessConfiguration ??= ServerlessConfigurationFactory?.Build();
    }

} // End Of Class

